<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Color Opacity Generator','description'=>'Generate CSS rgba values from a color and opacity.','url'=>'https://smarttoolz.in/tools/color-opacity-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Color Opacity Generator</h1><p>Generate an RGBA color value with a live preview.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="c" type="color" value="#5b43ff"><label>Opacity %<input id="o" type="range" min="0" max="100" value="50"></label><p id="r" style="font-size:18px;font-weight:800"></p><div id="p" style="height:100px;border-radius:12px"></div></div></section></main><script>function go(){let h=c.value.slice(1),x=[0,2,4].map(i=>parseInt(h.slice(i,i+2),16));r.textContent=`rgba(${x.join(',')},${o.value/100})`;p.style.background=r.textContent}c.oninput=o.oninput=go;go()</script><?php smarttoolz_tool_page_end(); ?>